-- 092_payment_milestone_notifications.sql
-- Roadmap G.37: actionable due/readiness notifications from active schedule + PM observations.
CREATE OR REPLACE FUNCTION public.get_project_payment_milestone_notifications(p_project_id bigint,p_as_of_date date DEFAULT current_date)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();s public.project_payment_schedules%ROWTYPE;visit_id bigint;verified numeric;verified_at date;source text;
BEGIN IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_NOTIFICATIONS_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_as_of_date IS NULL THEN RAISE EXCEPTION'INVALID_NOTIFICATION_DATE'USING ERRCODE='22023';END IF;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id AND status='ACTIVE'ORDER BY version_number DESC LIMIT 1;SELECT id,visit_date INTO visit_id,verified_at FROM public.site_visits WHERE project_id=p_project_id ORDER BY visit_date DESC,id DESC LIMIT 1;IF visit_id IS NOT NULL THEN SELECT round(avg(observed_progress),2)INTO verified FROM public.site_visit_wps WHERE site_visit_id=visit_id AND observed_progress IS NOT NULL;source:=CASE WHEN verified IS NULL THEN NULL ELSE'LATEST_PM_SITE_VISIT_AVERAGE'END;END IF;
RETURN jsonb_build_object('projectId',p_project_id,'asOfDate',p_as_of_date,'activeScheduleId',s.id,'verifiedProgress',verified,'verifiedProgressDate',verified_at,'verifiedProgressSource',source,'notifications',CASE WHEN s.id IS NULL THEN'[]'::jsonb ELSE COALESCE((SELECT jsonb_agg(jsonb_build_object('milestoneId',q.id,'sequenceNumber',q.sequence_number,'title',q.title,'plannedDate',q.planned_date,'dueInDays',q.planned_date-p_as_of_date,'requiredProgress',q.required_progress,'currentVerifiedProgress',verified,'readiness',CASE WHEN verified IS NULL THEN'UNVERIFIED'WHEN verified>=q.required_progress THEN'READY_FOR_REVIEW'ELSE'NOT_READY'END,'severity',CASE WHEN q.planned_date<p_as_of_date THEN'OVERDUE'WHEN q.planned_date-p_as_of_date<=10 THEN'DUE_SOON'ELSE'UPCOMING'END,'message',CASE WHEN verified IS NULL THEN q.title||' is due in '||(q.planned_date-p_as_of_date)||' days. PM-verified progress is unavailable; readiness cannot be confirmed.'WHEN verified>=q.required_progress THEN q.title||' is due in '||(q.planned_date-p_as_of_date)||' days. Required progress '||q.required_progress||'%. Current PM-verified progress '||verified||'%. Ready for review.'ELSE q.title||' is due in '||(q.planned_date-p_as_of_date)||' days. Required progress '||q.required_progress||'%. Current PM-verified progress '||verified||'%. Not ready for certification.'END)ORDER BY q.planned_date,q.sequence_number)FROM(SELECT m.*,sum(m.percentage)OVER(ORDER BY m.sequence_number)required_progress FROM public.project_payment_milestones m WHERE m.payment_schedule_id=s.id AND m.status IN('UPCOMING','READY_FOR_REVIEW'))q WHERE q.planned_date-p_as_of_date<=30),'[]'::jsonb)END);END;$$;
REVOKE ALL ON FUNCTION public.get_project_payment_milestone_notifications(bigint,date)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_project_payment_milestone_notifications(bigint,date)TO authenticated;
